C++ <pre><code>class Solution {
public:
    vector&lt;int&gt; searchRange(vector&lt;int&gt;&amp; nums, int target) {
        if(nums.empty())  return {-1,-1};

        int left = 0,right = nums.size()-1;

        while (left &lt;= right) {
            int mid = left + (right - left) / 2; 
            if (nums[mid] &gt;= target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        int start = left;
        if (start &gt;= nums.size() || nums[start] != target) {
            return {-1, -1};
        }

        left = 0;
        right = nums.size() - 1;
        while (left &lt;= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] &lt;= target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        int end = right;

        return {start, end};
    }
};
